const VERSION_1: &str = "0.1.0";
const VERSION_2: &str = "0.2.0";

#[derive(Debug, Default)]
struct FakeProbe {
    calls: AtomicUsize,
    fail: bool,
}

impl FakeProbe {
    const fn failing() -> Self {
        Self {
            calls: AtomicUsize::new(0),
            fail: true,
        }
    }

    fn calls(&self) -> usize {
        self.calls.load(Ordering::Relaxed)
    }
}

impl NativeEngineProbe for FakeProbe {
    fn probe(&self, _tree: &Path, _manifest: &ManifestV2) -> wxml_delivery::Result<()> {
        self.calls.fetch_add(1, Ordering::Relaxed);
        if self.fail {
            return Err(DeliveryError::Runtime("injected probe failure".to_owned()));
        }
        Ok(())
    }
}

#[derive(Debug)]
struct FailAt {
    point: FailPoint,
}

impl InstallHooks for FailAt {
    fn checkpoint(&self, point: FailPoint) -> wxml_delivery::Result<()> {
        if point == self.point {
            return Err(DeliveryError::Runtime(format!(
                "injected failure at {point:?}"
            )));
        }
        Ok(())
    }
}

const fn expected(version: &str) -> ExpectedManifestV2<'_> {
    ExpectedManifestV2 {
        version: Some(version),
        platform: Some(NATIVE_PACKAGE_PLATFORM),
        protocol_version: Some(2),
    }
}

struct FixtureBuilder {
    root: PathBuf,
    files: Vec<FileEntry>,
}

impl FixtureBuilder {
    fn new(root: &Path) -> Self {
        fs::create_dir_all(root).unwrap();
        Self {
            root: root.to_path_buf(),
            files: Vec::new(),
        }
    }

    fn file(&mut self, path: &str, bytes: &[u8], mode: u32) {
        let destination = self.root.join(path);
        fs::create_dir_all(destination.parent().unwrap()).unwrap();
        fs::write(&destination, bytes).unwrap();
        set_mode(&destination, mode).unwrap();
        self.files.push(FileEntry {
            path: path.to_owned(),
            sha256: sha256_bytes(bytes),
            size: u64::try_from(bytes.len()).unwrap(),
            mode: format!("{mode:04o}"),
        });
    }

    fn hash(&self, path: &str) -> String {
        self.files
            .iter()
            .find(|file| file.path == path)
            .unwrap()
            .sha256
            .clone()
    }
}

fn stage_fixture(root: &InstallRoot, version: &str) -> (PathBuf, ManifestV2) {
    stage_fixture_variant(root, version, "")
}

fn stage_fixture_variant(root: &InstallRoot, version: &str, marker: &str) -> (PathBuf, ManifestV2) {
    let staged = root.new_temp_dir("staged").unwrap();
    let manifest = build_fixture_variant(&staged, version, marker);
    (staged, manifest)
}

fn stage_fixture_with_scripts(
    root: &InstallRoot,
    version: &str,
    lsp_script: &str,
    installer_script: &str,
) -> (PathBuf, ManifestV2) {
    let staged = root.new_temp_dir("staged").unwrap();
    let manifest = build_fixture_with_scripts(&staged, version, "", lsp_script, installer_script);
    (staged, manifest)
}

fn build_fixture(root: &Path, version: &str) -> ManifestV2 {
    build_fixture_variant(root, version, "")
}

#[allow(clippy::too_many_lines)]
fn build_fixture_variant(root: &Path, version: &str, marker: &str) -> ManifestV2 {
    let lsp = format!("#!/bin/sh\nprintf 'wxml-lsp {version}\\n'\n");
    let installer = format!("#!/bin/sh\nprintf 'wxml-lsp-install {version}\\n'\n");
    build_fixture_with_scripts(root, version, marker, &lsp, &installer)
}

#[allow(clippy::too_many_lines)]
fn build_fixture_with_scripts(
    root: &Path,
    version: &str,
    marker: &str,
    lsp_script: &str,
    installer_script: &str,
) -> ManifestV2 {
    let mut builder = FixtureBuilder::new(root);
    builder.file("bin/wxml-lsp", lsp_script.as_bytes(), 0o755);
    builder.file("bin/wxml-lsp-install", installer_script.as_bytes(), 0o755);
    builder.file("engine/lib/tsc", b"\x7fELF-fixture-native-engine", 0o755);
    builder.file("engine/lib/tsc.sig", b"signature-placeholder\n", 0o644);
    builder.file("engine/LICENSE", b"Apache License fixture\n", 0o644);
    builder.file("engine/NOTICE.txt", b"NOTICE fixture\n", 0o644);
    builder.file("engine/package.json", b"{\"name\":\"fixture\"}\n", 0o644);
    builder.file("engine/lib/lib.d.ts", b"// lib.d.ts\n", 0o644);
    builder.file("engine/lib/lib.es5.d.ts", b"// lib.es5.d.ts\n", 0o644);
    builder.file("engine/lib/lib.es2020.d.ts", b"// lib.es2020.d.ts\n", 0o644);
    for index in 0..113 {
        builder.file(
            &format!("engine/lib/lib.f{index:03}.d.ts"),
            format!("// filler {index}\n").as_bytes(),
            0o644,
        );
    }
    typings_payload::write_payload(|path, bytes| builder.file(path, bytes, 0o644));
    builder.file("zed-extension/extension.wasm", b"\0asm-fixture", 0o644);
    builder.file(
        "zed-extension/extension.toml",
        b"id = \"wxml-lsp\"\n",
        0o644,
    );
    builder.file(
        "provenance.json",
        format!("{{\"fixture\":true,\"marker\":\"{marker}\"}}\n").as_bytes(),
        0o644,
    );
    builder.file("THIRD_PARTY_LICENSES.md", b"# licenses\n", 0o644);

    let standard = compute_type_asset_bundle(
        &builder.files,
        "engine/lib",
        &[STANDARD_LIB_INCLUDE.to_owned()],
    )
    .unwrap();
    assert_eq!(standard.file_count, STANDARD_LIB_FILE_COUNT);
    let typings =
        compute_type_asset_bundle(&builder.files, MINIPROGRAM_TYPINGS_ROOT, &["**".to_owned()])
            .unwrap();
    assert_eq!(typings.file_count, MINIPROGRAM_TYPINGS_FILE_COUNT);

    let manifest = ManifestV2 {
        schema_version: MANIFEST_SCHEMA_V2,
        package: "wxml-lsp".to_owned(),
        package_version: version.to_owned(),
        platform: NATIVE_PACKAGE_PLATFORM.to_owned(),
        protocol_version: 2,
        built_at: "2026-11-17T00:00:00Z".to_owned(),
        engine: EngineInfo {
            name: "typescript".to_owned(),
            version: ENGINE_VERSION.to_owned(),
            source_commit: ENGINE_SOURCE_COMMIT.to_owned(),
            distribution: ENGINE_DISTRIBUTION.to_owned(),
            distribution_url: "https://registry.npmjs.org/@typescript/typescript-linux-x64/-/typescript-linux-x64-7.1.0-beta.tgz".to_owned(),
            distribution_integrity: ENGINE_DISTRIBUTION_INTEGRITY.to_owned(),
            distribution_sha256: ENGINE_DISTRIBUTION_SHA256.to_owned(),
            distribution_size: ENGINE_DISTRIBUTION_SIZE,
            distribution_file_count: ENGINE_DISTRIBUTION_FILE_COUNT,
            distribution_unpacked_size: ENGINE_DISTRIBUTION_UNPACKED_SIZE,
            api_schema_version: 9,
            ast_header_bytes: 64,
            license: ENGINE_LICENSE.to_owned(),
            license_files: vec!["engine/LICENSE".to_owned(), "engine/NOTICE.txt".to_owned()],
            binary: "engine/lib/tsc".to_owned(),
            probe: EngineProbe {
                args: vec!["--version".to_owned()],
                expect_prefix: ENGINE_PROBE_PREFIX.to_owned(),
            },
        },
        type_assets: vec![
            TypeAsset {
                name: STANDARD_LIB_ASSET.to_owned(),
                version: ENGINE_VERSION.to_owned(),
                license: ENGINE_LICENSE.to_owned(),
                root: "engine/lib".to_owned(),
                include: vec![STANDARD_LIB_INCLUDE.to_owned()],
                file_count: standard.file_count,
                sha256: standard.sha256,
                license_files: vec!["engine/LICENSE".to_owned(), "engine/NOTICE.txt".to_owned()],
            },
            TypeAsset {
                name: MINIPROGRAM_TYPINGS_ASSET.to_owned(),
                version: MINIPROGRAM_TYPINGS_VERSION.to_owned(),
                license: MINIPROGRAM_TYPINGS_LICENSE.to_owned(),
                root: MINIPROGRAM_TYPINGS_ROOT.to_owned(),
                include: vec!["**".to_owned()],
                file_count: typings.file_count,
                sha256: typings.sha256,
                license_files: vec![format!("{MINIPROGRAM_TYPINGS_ROOT}/LICENSE")],
            },
        ],
        binaries: vec![
            NativeBinaryArtifact {
                kind: NativeArtifactKind::Rust,
                name: "wxml-lsp".to_owned(),
                path: "bin/wxml-lsp".to_owned(),
                version: version.to_owned(),
                protocol_version: None,
                sha256: builder.hash("bin/wxml-lsp"),
            },
            NativeBinaryArtifact {
                kind: NativeArtifactKind::Rust,
                name: "wxml-lsp-install".to_owned(),
                path: "bin/wxml-lsp-install".to_owned(),
                version: version.to_owned(),
                protocol_version: None,
                sha256: builder.hash("bin/wxml-lsp-install"),
            },
            NativeBinaryArtifact {
                kind: NativeArtifactKind::NativeEngine,
                name: "tsgo".to_owned(),
                path: "engine/lib/tsc".to_owned(),
                version: ENGINE_VERSION.to_owned(),
                protocol_version: Some(2),
                sha256: builder.hash("engine/lib/tsc"),
            },
            NativeBinaryArtifact {
                kind: NativeArtifactKind::ZedExtension,
                name: "zed-extension".to_owned(),
                path: "zed-extension/extension.wasm".to_owned(),
                version: "0.0.1".to_owned(),
                protocol_version: None,
                sha256: builder.hash("zed-extension/extension.wasm"),
            },
        ],
        files: builder.files,
    };
    manifest.validate(expected(version)).unwrap();
    atomic_write(
        &root.join("manifest.json"),
        &manifest.to_json().unwrap(),
        0o644,
    )
    .unwrap();
    let checksums = checksums_for_tree_v2(root, &manifest).unwrap();
    atomic_write(&root.join("SHA256SUMS"), &checksums, 0o644).unwrap();
    verify_tree_v2(root, expected(version)).unwrap();
    manifest
}

/// Rewrites `provenance.json` with lock-derived identity fields, updates the
/// manifest entry and checksums, and returns the parsed manifest.
fn write_lock_provenance(root: &Path, version: &str, corrupt_digest: Option<&str>) {
    let manifest_path = root.join("manifest.json");
    let mut manifest = read_manifest_v2(root, expected(version)).unwrap();
    let under = |root_path: &str| -> Vec<FileEntry> {
        manifest
            .files
            .iter()
            .filter(|file| file.path.starts_with(&format!("{root_path}/")))
            .cloned()
            .collect()
    };
    let engine_files = under("engine");
    let typings_files = under(MINIPROGRAM_TYPINGS_ROOT);
    let engine_digest = canonical_tree_digest(&engine_files, "engine").unwrap();
    let typings_digest = canonical_tree_digest(&typings_files, MINIPROGRAM_TYPINGS_ROOT).unwrap();
    let engine_count = u64::try_from(engine_files.len()).unwrap();
    let typings_count = u64::try_from(typings_files.len()).unwrap();
    let engine_bytes: u64 = engine_files.iter().map(|file| file.size).sum();
    let typings_bytes: u64 = typings_files.iter().map(|file| file.size).sum();
    let value = json!({
        "schemaVersion": 1,
        "package": "wxml-lsp",
        "packageVersion": version,
        "assetsLockSha256": "a".repeat(64),
        "assets": [
            {
                "name": "typescript-native-engine",
                "version": ENGINE_VERSION,
                "license": ENGINE_LICENSE,
                "packageRoot": "engine",
                "payloadTreeDigest": corrupt_digest.unwrap_or(engine_digest.as_str()),
                "fileCount": engine_count,
                "totalBytes": engine_bytes,
                "tarball": {
                    "integrity": ENGINE_DISTRIBUTION_INTEGRITY,
                    "sha256": ENGINE_DISTRIBUTION_SHA256,
                    "size": ENGINE_DISTRIBUTION_SIZE,
                },
            },
            {
                "name": MINIPROGRAM_TYPINGS_ASSET,
                "version": MINIPROGRAM_TYPINGS_VERSION,
                "license": MINIPROGRAM_TYPINGS_LICENSE,
                "packageRoot": MINIPROGRAM_TYPINGS_ROOT,
                "payloadTreeDigest": corrupt_digest.unwrap_or(typings_digest.as_str()),
                "fileCount": typings_count,
                "totalBytes": typings_bytes,
                "tarball": {
                    "integrity": "sha512-2CirO+C1z5RmKXDqTUSNbuyouHf5d0/KJTt+Qqi1EsiQYs8jlYhq7yWjp6EdTcJpvZzjuefZQCcDixYbrgIqow==",
                    "sha256": "c".repeat(64),
                    "size": 449_429,
                },
            },
        ],
        "engine": {
            "name": "typescript",
            "version": ENGINE_VERSION,
            "sourceCommit": ENGINE_SOURCE_COMMIT,
            "binary": {
                "path": "engine/lib/tsc",
                "sha256": manifest.file("engine/lib/tsc").unwrap().sha256.clone(),
                "size": manifest.file("engine/lib/tsc").unwrap().size,
                "mode": "0755",
                "measurement": "measured"
            }
        }
    });
    let mut bytes = serde_json::to_vec_pretty(&value).unwrap();
    bytes.push(b'\n');
    fs::write(root.join("provenance.json"), &bytes).unwrap();
    set_mode(&root.join("provenance.json"), 0o644).unwrap();
    let entry = manifest
        .files
        .iter_mut()
        .find(|file| file.path == "provenance.json")
        .unwrap();
    entry.sha256 = sha256_bytes(&bytes);
    entry.size = u64::try_from(bytes.len()).unwrap();
    atomic_write(&manifest_path, &manifest.to_json().unwrap(), 0o644).unwrap();
    let checksums = checksums_for_tree_v2(root, &manifest).unwrap();
    atomic_write(&root.join("SHA256SUMS"), &checksums, 0o644).unwrap();
}

fn write_legacy_version(root: &InstallRoot, version: &str) -> String {
    let directory = root.versions_dir().join(version);
    fs::create_dir_all(&directory).unwrap();
    let manifest = json!({
        "schemaVersion": 1,
        "package": "wxml-lsp",
        "packageVersion": version,
        "platform": NATIVE_PACKAGE_PLATFORM,
        "protocolVersion": 2,
        "node": {"minimumVersion": "24.0.0", "backendVersion": "0.1.0"},
        "builtAt": "2026-01-01T00:00:00Z",
        "binaries": [{
            "kind": "node-backend",
            "name": "node-backend",
            "path": "bin/wxml-type-backend/server.js",
            "version": "0.1.0",
            "sha256": "0".repeat(64)
        }],
        "files": [],
        "unknownLegacyField": true
    });
    fs::write(
        directory.join("manifest.json"),
        serde_json::to_vec_pretty(&manifest).unwrap(),
    )
    .unwrap();
    set_mode(&directory.join("manifest.json"), 0o644).unwrap();
    root.switch(version).unwrap();
    tree_fingerprint(&directory).unwrap()
}

fn active_version(root: &InstallRoot) -> String {
    root.current_version().unwrap().unwrap()
}

fn state_bytes(root: &InstallRoot) -> Vec<u8> {
    fs::read(root.path().join("state.json")).unwrap()
}

fn journals_for(root: &InstallRoot, target: &str) -> Vec<Journal> {
    Journal::list(root)
        .unwrap()
        .into_iter()
        .filter(|journal| journal.target == target)
        .collect()
}

fn write_stale_journal(
    root: &InstallRoot,
    op: wxml_delivery::state::TransactionOp,
    target: &str,
    previous: Option<&str>,
    state: TransactionState,
) {
    let now = "2026-11-17T00:00:00Z";
    let mut journal = Journal::new(op, target, previous, now).unwrap();
    if state != TransactionState::Staged {
        journal.transition(state, now).unwrap();
    }
    journal.write(root).unwrap();
}

fn assert_tmp_empty(root: &InstallRoot) {
    if let Ok(mut entries) = fs::read_dir(root.tmp_dir()) {
        assert!(entries.next().is_none(), "staging files were left in tmp/");
    }
}

fn install(
    root: &InstallRoot,
    staged: &Path,
    version: &str,
    probe: &dyn NativeEngineProbe,
    hooks: &dyn InstallHooks,
) -> wxml_delivery::Result<NativeInstallOutcome> {
    install_native(root, staged, expected(version), probe, hooks)
}

#[test]
fn v2_manifest_round_trips_and_rejects_v1_or_node_fields() {
    let base = TempDir::new("native-manifest");
    let manifest = build_fixture(base.path(), VERSION_1);
    let bytes = manifest.to_json().unwrap();
    let reparsed = read_manifest_v2(base.path(), expected(VERSION_1)).unwrap();
    assert_eq!(manifest, reparsed);

    let value: Value = serde_json::from_slice(&bytes).unwrap();
    assert_eq!(value["schemaVersion"], 2);
    assert!(value.get("node").is_none(), "v2 must not contain `node`");

    let mut with_node = value;
    with_node["node"] = json!({"minimumVersion": "24.0.0"});
    let error = wxml_delivery::manifest_v2::parse_manifest_v2(
        &serde_json::to_vec(&with_node).unwrap(),
        expected(VERSION_1),
    )
    .unwrap_err();
    assert!(error.to_string().contains("malformed"), "{error}");

    let v1 = br#"{"schemaVersion":1,"package":"wxml-lsp","packageVersion":"0.1.0","platform":"linux-x86_64"}"#;
    let error = wxml_delivery::manifest_v2::parse_manifest_v2(v1, expected(VERSION_1)).unwrap_err();
    assert!(error.to_string().contains("legacy Node package"), "{error}");
    assert_eq!(
        read_manifest_schema(base.path()).unwrap(),
        wxml_delivery::manifest_v2::ManifestSchema::V2
    );
}

#[test]
fn v1_manifest_is_a_read_only_projection_and_cannot_be_reinterpreted() {
    let base = TempDir::new("native-legacy-read");
    let root = InstallRoot::create(&base.path().join("root")).unwrap();
    let legacy = base.path().join("legacy");
    fs::create_dir_all(&legacy).unwrap();
    fs::write(
        legacy.join("manifest.json"),
        serde_json::to_vec_pretty(&json!({
            "schemaVersion": 1,
            "package": "wxml-lsp",
            "packageVersion": "0.0.9",
            "platform": NATIVE_PACKAGE_PLATFORM,
            "protocolVersion": 2,
            "node": {"minimumVersion": "24.0.0", "backendVersion": "0.1.0"},
            "unknownLegacyField": true
        }))
        .unwrap(),
    )
    .unwrap();
    let projection = read_legacy_manifest(&legacy).unwrap();
    assert_eq!(projection.package_version, "0.0.9");
    assert_eq!(projection.schema_version, 1);
    assert_eq!(
        read_manifest_schema(&legacy).unwrap(),
        wxml_delivery::manifest_v2::ManifestSchema::V1
    );
    assert!(read_manifest_v2(&legacy, ExpectedManifestV2::default()).is_err());

    let _ = root;
    let native = base.path().join("native");
    build_fixture(&native, VERSION_1);
    assert!(read_legacy_manifest(&native).is_err());
}

#[test]
fn asset_sri_sha256_and_manifest_identity_are_checked() {
    let bytes = b"release archive bytes";
    let sri = sha512_sri_bytes(bytes).to_sri();
    let sha256 = sha256_bytes(bytes);
    verify_asset_bytes(bytes, &sri, &sha256, u64::try_from(bytes.len()).unwrap()).unwrap();

    let wrong_sri = sha512_sri_bytes(b"other archive").to_sri();
    let error = verify_asset_bytes(
        bytes,
        &wrong_sri,
        &sha256,
        u64::try_from(bytes.len()).unwrap(),
    )
    .unwrap_err();
    assert!(error.to_string().contains("SRI"), "{error}");
    let error = verify_asset_bytes(
        bytes,
        &sri,
        &"0".repeat(64),
        u64::try_from(bytes.len()).unwrap(),
    )
    .unwrap_err();
    assert!(error.to_string().contains("SHA-256"), "{error}");
    let error = verify_asset_bytes(bytes, &sri, &sha256, 1).unwrap_err();
    assert!(error.to_string().contains("size"), "{error}");

    let base = TempDir::new("native-identity");
    let mut manifest = build_fixture(base.path(), VERSION_1);
    manifest.engine.distribution_integrity = wrong_sri;
    assert!(manifest.validate(expected(VERSION_1)).is_err());

    let mut manifest = build_fixture(&base.path().join("second"), VERSION_1);
    manifest.engine.distribution_sha256 = "0".repeat(63);
    assert!(manifest.validate(expected(VERSION_1)).is_err());

    let mut manifest = build_fixture(&base.path().join("third"), VERSION_1);
    manifest.engine.version = "7.0.2".to_owned();
    assert!(manifest.validate(expected(VERSION_1)).is_err());
}

#[test]
fn tree_verification_rejects_extra_missing_tampered_and_mode_changes() {
    let base = TempDir::new("native-tree-tamper");
    build_fixture(base.path(), VERSION_1);
    verify_tree_v2(base.path(), expected(VERSION_1)).unwrap();

    let extra = base.path().join("extra.txt");
    fs::write(&extra, b"extra").unwrap();
    set_mode(&extra, 0o644).unwrap();
    assert!(verify_tree_v2(base.path(), expected(VERSION_1)).is_err());
    fs::remove_file(&extra).unwrap();

    let dts = base.path().join("engine/lib/lib.es2020.d.ts");
    let original = fs::read(&dts).unwrap();
    fs::write(&dts, b"// tampered\n").unwrap();
    assert!(verify_tree_v2(base.path(), expected(VERSION_1)).is_err());
    fs::write(&dts, original).unwrap();
    set_mode(&dts, 0o644).unwrap();
    verify_tree_v2(base.path(), expected(VERSION_1)).unwrap();

    let index = base
        .path()
        .join("typings/miniprogram-api-typings/index.d.ts");
    let original = fs::read(&index).unwrap();
    fs::remove_file(&index).unwrap();
    assert!(verify_tree_v2(base.path(), expected(VERSION_1)).is_err());
    fs::write(&index, original).unwrap();
    set_mode(&index, 0o644).unwrap();

    set_mode(&dts, 0o755).unwrap();
    assert!(verify_tree_v2(base.path(), expected(VERSION_1)).is_err());
    set_mode(&dts, 0o644).unwrap();

    let manifest = base.path().join("manifest.json");
    let original = fs::read(&manifest).unwrap();
    fs::write(&manifest, [original.as_slice(), b"\n"].concat()).unwrap();
    assert!(verify_tree_v2(base.path(), expected(VERSION_1)).is_err());
    fs::write(&manifest, original).unwrap();
    set_mode(&manifest, 0o644).unwrap();

    let license = base.path().join("engine/LICENSE");
    let original = fs::read(&license).unwrap();
    fs::remove_file(&license).unwrap();
    assert!(verify_tree_v2(base.path(), expected(VERSION_1)).is_err());
    fs::write(&license, original).unwrap();
    set_mode(&license, 0o644).unwrap();
    verify_tree_v2(base.path(), expected(VERSION_1)).unwrap();
}

#[test]
fn provenance_lock_identity_binds_installed_type_assets() {
    let base = TempDir::new("native-provenance-lock");
    build_fixture(base.path(), VERSION_1);
    write_lock_provenance(base.path(), VERSION_1, None);
    verify_tree_v2(base.path(), expected(VERSION_1)).unwrap();
    // `read_manifest_v2` itself must reject a lock identity that disagrees
    // with the manifest payload, not only the full tree verifier.
    read_manifest_v2(base.path(), expected(VERSION_1)).unwrap();

    let bad = "0".repeat(64);
    write_lock_provenance(base.path(), VERSION_1, Some(&bad));
    let error = verify_tree_v2(base.path(), expected(VERSION_1)).unwrap_err();
    assert!(error.to_string().contains("payloadTreeDigest"), "{error}");
    let error = read_manifest_v2(base.path(), expected(VERSION_1)).unwrap_err();
    assert!(error.to_string().contains("payloadTreeDigest"), "{error}");
}

fn real_assets_lock() -> AssetsLock {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../assets.lock.json");
    wxml_delivery::provision::read_assets_lock(&path)
        .expect("repository assets.lock.json")
        .lock
}

/// Replaces the synthetic engine/typings payload with the frozen lock table.
fn manifest_with_real_lock_payload(base: &Path) -> (ManifestV2, AssetsLock) {
    let mut manifest = build_fixture(base, VERSION_1);
    let lock = real_assets_lock();
    let engine = lock.asset(ENGINE_ASSET_NAME).expect("engine asset");
    let typings = lock.asset(TYPINGS_ASSET_NAME).expect("typings asset");
    let typings_prefix = format!("{}/", typings.package_root);
    manifest.files.retain(|file| {
        !(file.path.starts_with("engine/") || file.path.starts_with(&typings_prefix))
    });
    manifest.files.extend(engine.payload.files.iter().cloned());
    manifest.files.extend(typings.payload.files.iter().cloned());
    manifest
        .files
        .sort_by(|left, right| left.path.cmp(&right.path));

    for (asset, bundle_name, license_files) in [
        (engine, STANDARD_LIB_ASSET, &engine.license_files),
        (typings, MINIPROGRAM_TYPINGS_ASSET, &typings.license_files),
    ] {
        let bundle = asset
            .payload
            .bundles
            .iter()
            .find(|bundle| bundle.name == bundle_name)
            .expect("payload bundle");
        let declared = manifest
            .type_assets
            .iter_mut()
            .find(|declared| declared.name == bundle_name)
            .expect("declared type asset");
        declared.root.clone_from(&bundle.root);
        declared.include.clone_from(&bundle.include);
        declared.file_count = bundle.file_count;
        declared.sha256.clone_from(&bundle.sha256);
        declared.license_files.clone_from(license_files);
    }
    let engine_file = manifest
        .file("engine/lib/tsc")
        .expect("lock engine file")
        .clone();
    let native = manifest
        .binaries
        .iter_mut()
        .find(|artifact| artifact.kind == NativeArtifactKind::NativeEngine)
        .expect("native engine artifact");
    native.sha256 = engine_file.sha256;

    manifest.validate(expected(VERSION_1)).unwrap();
    (manifest, lock)
}

#[test]
fn manifest_cross_checks_type_assets_and_binaries_against_the_lock() {
    let base = TempDir::new("native-lock-cross-check");
    let (mut manifest, lock) = manifest_with_real_lock_payload(base.path());
    manifest.validate_against_lock(&lock).unwrap();

    let mut missing = manifest.clone();
    missing.files.retain(|file| file.path != "engine/README.md");
    let error = missing.validate_against_lock(&lock).unwrap_err();
    assert!(error.to_string().contains("payload table"), "{error}");

    let mut extra = manifest.clone();
    extra.files.push(FileEntry {
        path: "engine/lib/extra.txt".to_owned(),
        sha256: "0".repeat(64),
        size: 1,
        mode: "0644".to_owned(),
    });
    let error = extra.validate_against_lock(&lock).unwrap_err();
    assert!(error.to_string().contains("payload table"), "{error}");

    let mut altered = manifest.clone();
    let readme = altered
        .files
        .iter_mut()
        .find(|file| file.path == "engine/README.md")
        .unwrap();
    readme.sha256 = "0".repeat(64);
    let error = altered.validate_against_lock(&lock).unwrap_err();
    assert!(error.to_string().contains("payload table"), "{error}");

    let mut wrong_asset = manifest.clone();
    let standard = wrong_asset
        .type_assets
        .iter_mut()
        .find(|asset| asset.name == STANDARD_LIB_ASSET)
        .unwrap();
    standard.file_count += 1;
    let error = wrong_asset.validate_against_lock(&lock).unwrap_err();
    assert!(error.to_string().contains("fileCount/sha256"), "{error}");

    let mut wrong_bundle = manifest.clone();
    let typings = wrong_bundle
        .type_assets
        .iter_mut()
        .find(|asset| asset.name == MINIPROGRAM_TYPINGS_ASSET)
        .unwrap();
    typings.root = "typings/other".to_owned();
    let error = wrong_bundle.validate_against_lock(&lock).unwrap_err();
    assert!(error.to_string().contains("root/include"), "{error}");

    manifest.engine.version = "7.0.2".to_owned();
    let error = manifest.validate_against_lock(&lock).unwrap_err();
    assert!(error.to_string().contains("engine identity"), "{error}");
}

