#[test]
fn index_v2_round_trips_and_rejects_unknown_installer_schema() {
    let base = TempDir::new("native-index");
    let manifest = build_fixture(&base.path().join("tree"), VERSION_1);
    let archive = b"fixture archive";
    let release = ReleaseV2 {
        version: VERSION_1.to_owned(),
        platform: NATIVE_PACKAGE_PLATFORM.to_owned(),
        protocol_version: 2,
        engine_version: ENGINE_VERSION.to_owned(),
        engine_source_commit: ENGINE_SOURCE_COMMIT.to_owned(),
        engine_protocol_version: 2,
        engine_api_schema_version: 9,
        engine_ast_header_bytes: 64,
        engine_distribution: ENGINE_DISTRIBUTION.to_owned(),
        engine_integrity: ENGINE_DISTRIBUTION_INTEGRITY.to_owned(),
        min_installer_schema: 2,
        archive: format!("wxml-lsp-{VERSION_1}-{NATIVE_PACKAGE_PLATFORM}.tar.gz"),
        archive_integrity: sha512_sri_bytes(archive).to_sri(),
        sha256: sha256_bytes(archive),
        size: u64::try_from(archive.len()).unwrap(),
    };
    assert!(release.matches_manifest(&manifest));
    let archive_path = base.path().join("archive.tar.gz");
    fs::write(&archive_path, archive).unwrap();
    release.verify_archive(&archive_path).unwrap();
    fs::write(&archive_path, b"tampered").unwrap();
    assert!(release.verify_archive(&archive_path).is_err());

    let mut index = IndexV2::empty();
    index.upsert(release);
    index.validate().unwrap();
    let path = base.path().join("index.json");
    atomic_write(&path, &index.to_json().unwrap(), 0o644).unwrap();
    assert_eq!(read_index_v2(&path).unwrap(), index);

    let mut invalid = index.clone();
    invalid.releases[0].min_installer_schema = 3;
    assert!(invalid.validate().is_err());

    let mut value: Value = serde_json::from_slice(&index.to_json().unwrap()).unwrap();
    value["unknownField"] = json!(true);
    let error =
        serde_json::from_slice::<IndexV2>(&serde_json::to_vec(&value).unwrap()).unwrap_err();
    assert!(error.to_string().contains("unknown field"), "{error}");
}

