#[test]
fn safe_extraction_allowlist_rejects_extra_entries() {
    use flate2::Compression;
    use flate2::write::GzEncoder;
    use std::io::Cursor;
    use tar::{Builder, Header};

    let base = TempDir::new("native-extract");
    let archive = base.path().join("a.tar.gz");
    let file = fs::File::create(&archive).unwrap();
    let encoder = GzEncoder::new(file, Compression::default());
    let mut builder = Builder::new(encoder);
    for (name, body) in [("a", &b"a"[..]), ("extra", &b"extra"[..])] {
        let mut header = Header::new_gnu();
        header.set_entry_type(tar::EntryType::Regular);
        header.set_size(u64::try_from(body.len()).unwrap());
        header.set_mode(0o644);
        header.set_mtime(0);
        header.set_uid(0);
        header.set_gid(0);
        header.set_path(name).unwrap();
        header.set_cksum();
        builder.append(&header, Cursor::new(body)).unwrap();
    }
    builder.finish().unwrap();
    builder.into_inner().unwrap().finish().unwrap();

    let allowed = BTreeSet::from(["a".to_owned()]);
    let destination = base.path().join("out");
    let error = extract_tar_gz_allowlisted(&archive, &destination, &allowed).unwrap_err();
    assert!(
        matches!(error, DeliveryError::UnsafeArchive(_)),
        "{error:?}"
    );
    assert!(!destination.exists());
}

