#[test]
fn archive_allowlist_extracts_and_verifies_a_native_tree() {
    let base = TempDir::new("native-archive-allowlist");
    let tree = base.path().join("tree");
    let manifest = build_fixture(&tree, VERSION_1);
    let mut entries = manifest.files;
    for name in ["manifest.json", "SHA256SUMS"] {
        let path = tree.join(name);
        let metadata = fs::metadata(&path).unwrap();
        entries.push(FileEntry {
            path: name.to_owned(),
            sha256: sha256_file(&path).unwrap(),
            size: metadata.len(),
            mode: "0644".to_owned(),
        });
    }
    entries.sort_by(|left, right| left.path.cmp(&right.path));
    let archive = base.path().join("package.tar.gz");
    create_tar_gz(&tree, &archive, &entries, 0).unwrap();
    let allowed: BTreeSet<String> = entries.iter().map(|file| file.path.clone()).collect();
    let destination = base.path().join("extracted");
    extract_tar_gz_allowlisted(&archive, &destination, &allowed).unwrap();
    verify_tree_v2(&destination, expected(VERSION_1)).unwrap();
}

