#[test]
fn symlinked_root_layout_paths_are_rejected() {
    for name in ["versions", "tmp", "txn", "cache"] {
        let base = TempDir::new(&format!("native-layout-{name}"));
        let root = InstallRoot::create(&base.path().join("root")).unwrap();
        let outside = base.path().join("outside");
        fs::create_dir_all(&outside).unwrap();
        std::os::unix::fs::symlink(&outside, root.path().join(name)).unwrap();
        let error = recover_native(&root, &FakeProbe::default()).unwrap_err();
        assert!(matches!(error, DeliveryError::InstallState(_)), "{error:?}");
    }

    for name in ["versions", "tmp", "txn", "cache"] {
        let base = TempDir::new(&format!("native-layout-file-{name}"));
        let root = InstallRoot::create(&base.path().join("root")).unwrap();
        fs::write(root.path().join(name), b"not-a-directory").unwrap();
        let error = recover_native(&root, &FakeProbe::default()).unwrap_err();
        assert!(matches!(error, DeliveryError::InstallState(_)), "{error:?}");
    }

    let base = TempDir::new("native-layout-state");
    let root = InstallRoot::create(&base.path().join("root")).unwrap();
    let outside = base.path().join("state-outside");
    fs::write(&outside, b"{}").unwrap();
    std::os::unix::fs::symlink(&outside, root.path().join("state.json")).unwrap();
    let error = recover_native(&root, &FakeProbe::default()).unwrap_err();
    assert!(matches!(error, DeliveryError::InstallState(_)), "{error:?}");
}

